<template><section class="match-roster-card"><h3>本场比赛使用的名单</h3><p>补录当天或过去的比赛时，管理员可指定后来上传的名单并填写理由。报告已开始时只允许补齐缺失的一方，已有名单继续锁定；未来比赛按比赛日期读取有效名单。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p><button :disabled="busy" @click="load">刷新比赛名单</button><template v-if="data"><article v-for="item in data.items" :key="item.team_id"><h4>{{ item.team_id===data.schedule.team_a_id?data.schedule.team_a_name_snapshot:data.schedule.team_b_name_snapshot }} · {{ item.batch?'第 '+item.batch.version_no+' 版':'没有可用名单' }}</h4><p>{{ item.selection_reason }}</p><p v-if="item.edit_mode==='fill_missing'">本队原名单为空，可补齐名单；已有报告内容保持不变。</p><p v-if="item.edit_block_reason">{{ item.edit_block_reason }}</p><details><summary>查看本场名单（{{ item.players.length }}人）</summary><ul><li v-for="p in item.players" :key="p.id">{{ p.jersey_number }}号 · {{ p.player_name }}{{ p.is_captain?' · 队长':'' }}{{ p.is_goalkeeper?' · 守门员':'' }}</li></ul></details><form v-draft="{ value: { selected: selected[item.team_id], reason: reasons[item.team_id] } }" v-if="item.can_edit" @submit.prevent="change(item)"><label>选择{{ item.team_id===data.schedule.team_a_id?'主队':'客队' }}名单<select v-model="selected[item.team_id]" :disabled="busy" required><option value="">请选择版本</option><option v-for="b in data.candidates.filter(b=>b.team_id===item.team_id)" :key="b.id" :value="b.id">第 {{ b.version_no }} 版 · {{ b.effective_from || '历史名单' }} · {{ b.source_type==='legacy'?'历史导入':b.source_type==='admin_import'?'管理员导入':'线上审核' }}</option></select></label><label>切换理由<input v-model="reasons[item.team_id]" maxlength="500" required :disabled="busy" placeholder="说明本场为何采用此版名单"></label><button :disabled="busy||!selected[item.team_id]">{{ item.edit_mode==='fill_missing'?'补齐此队比赛名单':'切换此队比赛名单' }}</button></form></article><details v-if="data.events.length"><summary>名单选择记录</summary><ul><li v-for="(e,i) in data.events" :key="i">{{ e.reason }} · {{ e.created_at }} · {{ e.actor_admin_id?'管理员 #'+e.actor_admin_id:'系统保留' }}</li></ul></details></template></section></template>
<script setup>
import {ref,watch} from 'vue'
import api from '../api/http'
const props=defineProps({scheduleId:[String,Number]}),data=ref(null),busy=ref(false),error=ref(''),success=ref(''),selected=ref({}),reasons=ref({});let sequence=0
async function load(){const n=++sequence;error.value='';try{const r=await api.get(`/report/admin/schedule/${props.scheduleId}/rosters`);if(n===sequence)data.value=r.data}catch(e){if(n===sequence)error.value=e.response?.data?.message||'读取名单失败'}}
async function change(item){busy.value=true;error.value='';success.value='';try{const r=await api.put(`/report/admin/schedule/${props.scheduleId}/rosters`,{team_id:item.team_id,roster_batch_id:selected.value[item.team_id],reason:reasons.value[item.team_id],review_token:data.value.review_token});data.value=r.data;delete selected.value[item.team_id];delete reasons.value[item.team_id];success.value=item.edit_mode==='fill_missing'?'本场缺失名单已补齐，请刷新报告页面后继续填写。':'本场名单已切换，请刷新报告页面后继续填写。'}catch(e){error.value=e.response?.data?.message||'切换失败，请刷新核对'}finally{busy.value=false}}
watch(()=>props.scheduleId,load,{immediate:true})
</script>
<style scoped>
@layer legacy {
.match-roster-card{margin:20px 0;background:white;padding:24px;border-radius:12px}.match-roster-card p{line-height:1.7;color:#526477}.match-roster-card article{border-top:1px solid #dce4ed;padding:14px 0}.match-roster-card form{display:flex;flex-wrap:wrap;gap:12px;margin:14px 0;align-items:end}.match-roster-card label{display:flex;flex-direction:column;gap:8px;max-width:100%}.match-roster-card input,.match-roster-card select{padding:9px;border:1px solid #aabccc;border-radius:6px}.match-roster-card button{padding:10px;border:0;border-radius:6px;background:#195c83;color:white}.match-roster-card button:disabled{opacity:.5}.match-roster-card .error{color:#aa2333}
}
</style>
